import { lstat, open, readFile, readdir } from "node:fs/promises";
import { createHash } from "node:crypto";
import { dirname, isAbsolute, join, relative, resolve } from "node:path";
import { TextDecoder } from "node:util";

const root = resolve(import.meta.dirname, "..");
async function text(path) {
  return trustedRegularFileText(path);
}

function sameFileSystemObjectSnapshot(left, right) {
  return (
    (process.platform === "win32" || left.dev === right.dev) &&
    left.ino === right.ino &&
    left.mode === right.mode &&
    left.nlink === right.nlink &&
    left.size === right.size &&
    left.mtimeNs === right.mtimeNs &&
    left.ctimeNs === right.ctimeNs
  );
}

function sameRegularFileSnapshot(left, right) {
  return (
    left.isFile() && right.isFile() && sameFileSystemObjectSnapshot(left, right)
  );
}

function sameDirectorySnapshot(left, right) {
  return (
    left.isDirectory() &&
    right.isDirectory() &&
    sameFileSystemObjectSnapshot(left, right)
  );
}

async function trustedRegularFileText(path) {
  const absolute = resolve(root, path);
  const pathBefore = await lstat(absolute, { bigint: true });
  if (
    pathBefore.isSymbolicLink() ||
    !pathBefore.isFile() ||
    pathBefore.nlink !== 1n
  ) {
    throw new Error(
      `trusted input must be a regular single-link file: ${path}`,
    );
  }

  const handle = await open(absolute, "r");
  try {
    const openedBefore = await handle.stat({ bigint: true });
    if (!sameRegularFileSnapshot(pathBefore, openedBefore)) {
      throw new Error(`trusted input identity changed before read: ${path}`);
    }
    const source = await handle.readFile({ encoding: "utf8" });
    const openedAfter = await handle.stat({ bigint: true });
    const pathAfter = await lstat(absolute, { bigint: true });
    if (
      pathAfter.isSymbolicLink() ||
      !sameRegularFileSnapshot(openedBefore, openedAfter) ||
      !sameRegularFileSnapshot(openedAfter, pathAfter)
    ) {
      throw new Error(`trusted input changed during held-handle read: ${path}`);
    }
    return source;
  } finally {
    await handle.close();
  }
}

async function trustedRegularFileBytes(path) {
  const absolute = resolve(root, path);
  const pathBefore = await lstat(absolute, { bigint: true });
  if (
    pathBefore.isSymbolicLink() ||
    !pathBefore.isFile() ||
    pathBefore.nlink !== 1n
  ) {
    throw new Error(
      `trusted input must be a regular single-link file: ${path}`,
    );
  }

  const handle = await open(absolute, "r");
  try {
    const openedBefore = await handle.stat({ bigint: true });
    if (!sameRegularFileSnapshot(pathBefore, openedBefore)) {
      throw new Error(`trusted input identity changed before read: ${path}`);
    }
    const bytes = await handle.readFile();
    const openedAfter = await handle.stat({ bigint: true });
    const pathAfter = await lstat(absolute, { bigint: true });
    if (
      pathAfter.isSymbolicLink() ||
      !sameRegularFileSnapshot(openedBefore, openedAfter) ||
      !sameRegularFileSnapshot(openedAfter, pathAfter)
    ) {
      throw new Error(`trusted input changed during held-handle read: ${path}`);
    }
    return bytes;
  } finally {
    await handle.close();
  }
}

async function trustedDirectoryEntryInventory(path) {
  const absolute = resolve(root, path);
  const directoryBefore = await lstat(absolute, { bigint: true });
  if (directoryBefore.isSymbolicLink() || !directoryBefore.isDirectory()) {
    throw new Error(
      `trusted inventory root must be a non-link directory: ${path}`,
    );
  }
  const entries = await readdir(absolute, { withFileTypes: true });
  const inventory = [];
  for (const entry of entries) {
    const entryPath = join(absolute, entry.name);
    const snapshot = await lstat(entryPath, { bigint: true });
    inventory.push({
      name: entry.name,
      kind: snapshot.isSymbolicLink()
        ? "symbolic-link"
        : snapshot.isFile()
          ? "file"
          : snapshot.isDirectory()
            ? "directory"
            : "other",
    });
  }
  const directoryAfter = await lstat(absolute, { bigint: true });
  if (!sameDirectorySnapshot(directoryBefore, directoryAfter)) {
    throw new Error(`trusted inventory directory changed during scan: ${path}`);
  }
  return inventory.sort((left, right) =>
    left.name.localeCompare(right.name, "en"),
  );
}

async function repositoryCargoOverridePaths() {
  const paths = [];
  const ignoredDirectoryNames = new Set([
    ".agents",
    ".codex",
    ".git",
    ".handoff",
    "node_modules",
    "target",
  ]);
  async function walk(directory) {
    for (const entry of await readdir(directory, { withFileTypes: true })) {
      const absolute = join(directory, entry.name);
      if (entry.name.toLowerCase() === ".cargo") {
        paths.push(relative(root, absolute).replaceAll("\\", "/"));
        continue;
      }
      if (
        entry.isDirectory() &&
        !ignoredDirectoryNames.has(entry.name.toLowerCase())
      ) {
        await walk(absolute);
      }
    }
  }
  await walk(root);
  return paths.sort((left, right) => left.localeCompare(right, "en"));
}

function cargoLockPackageRecords(source) {
  return [
    ...source.matchAll(
      /(?:^|\r?\n)\[\[package\]\]\r?\n(?<body>[\s\S]*?)(?=\r?\n\[\[package\]\]|\s*$)/gu,
    ),
  ].map((match) => {
    const field = (name) =>
      new RegExp(`^${name}\\s*=\\s*"(?<value>[^"]+)"\\s*$`, "mu").exec(
        match.groups.body,
      )?.groups.value ?? null;
    const dependencies =
      /^dependencies\s*=\s*\[(?<body>[\s\S]*?)^\]\s*$/mu.exec(match.groups.body)
        ?.groups.body ?? "";
    return {
      name: field("name"),
      version: field("version"),
      source: field("source"),
      checksum: field("checksum"),
      dependencies: [
        ...dependencies.matchAll(/^\s*"(?<name>[^"]+)",?\s*$/gmu),
      ].map((dependency) => dependency.groups.name),
    };
  });
}

function maskRustRange(characters, source, start, end) {
  for (let index = start; index < end; index += 1) {
    if (source[index] !== "\r" && source[index] !== "\n") {
      characters[index] = " ";
    }
  }
}

const rustLexicalCodeCache = new Map();
const compactRustCache = new Map();
function rustLexicalCodeUncached(source) {
  const characters = source.split("");
  for (let index = 0; index < source.length;) {
    if (source.startsWith("//", index)) {
      const end = source.indexOf("\n", index + 2);
      const exclusiveEnd = end === -1 ? source.length : end;
      maskRustRange(characters, source, index, exclusiveEnd);
      index = exclusiveEnd;
      continue;
    }
    if (source.startsWith("/*", index)) {
      let depth = 1;
      let cursor = index + 2;
      while (cursor < source.length && depth !== 0) {
        if (source.startsWith("/*", cursor)) {
          depth += 1;
          cursor += 2;
        } else if (source.startsWith("*/", cursor)) {
          depth -= 1;
          cursor += 2;
        } else {
          cursor += 1;
        }
      }
      if (depth !== 0) {
        throw new Error(
          "architecture scan found an unterminated Rust block comment",
        );
      }
      maskRustRange(characters, source, index, cursor);
      index = cursor;
      continue;
    }
    if (source[index] === "r") {
      let delimiter = index + 1;
      while (source[delimiter] === "#") {
        delimiter += 1;
      }
      if (source[delimiter] === '"') {
        const hashes = source.slice(index + 1, delimiter);
        const closing = `"${hashes}`;
        const close = source.indexOf(closing, delimiter + 1);
        if (close === -1) {
          throw new Error(
            "architecture scan found an unterminated Rust raw string",
          );
        }
        const exclusiveEnd = close + closing.length;
        maskRustRange(characters, source, index, exclusiveEnd);
        index = exclusiveEnd;
        continue;
      }
    }
    if (source[index] === '"') {
      let cursor = index + 1;
      let escaped = false;
      while (cursor < source.length) {
        if (!escaped && source[cursor] === '"') {
          cursor += 1;
          break;
        }
        if (!escaped && source[cursor] === "\\") {
          escaped = true;
        } else {
          escaped = false;
        }
        cursor += 1;
      }
      if (cursor > source.length || source[cursor - 1] !== '"') {
        throw new Error("architecture scan found an unterminated Rust string");
      }
      maskRustRange(characters, source, index, cursor);
      index = cursor;
      continue;
    }
    if (source[index] === "'") {
      const character =
        /^'(?:[^'\\\r\n]|\\(?:x[\dA-Fa-f]{2}|u\{[\dA-Fa-f_]+\}|.))'/u.exec(
          source.slice(index),
        );
      if (character !== null) {
        const exclusiveEnd = index + character[0].length;
        maskRustRange(characters, source, index, exclusiveEnd);
        index = exclusiveEnd;
        continue;
      }
    }
    index += 1;
  }
  return characters.join("");
}

function rustLexicalCode(source) {
  const cached = rustLexicalCodeCache.get(source);
  if (cached !== undefined) return cached;
  const lexical = rustLexicalCodeUncached(source);
  rustLexicalCodeCache.set(source, lexical);
  return lexical;
}

function cachedRustSourceAnalysis(cache, source, key, analyze) {
  let byKey = cache.get(source);
  if (byKey === undefined) {
    byKey = new Map();
    cache.set(source, byKey);
  }
  if (byKey.has(key)) return byKey.get(key);
  const result = analyze();
  byKey.set(key, result);
  return result;
}

function matchingRustDelimiter(sourceCode, opening, open, close) {
  let depth = 0;
  for (let index = opening; index < sourceCode.length; index += 1) {
    if (sourceCode[index] === open) {
      depth += 1;
    } else if (sourceCode[index] === close) {
      depth -= 1;
      if (depth === 0) {
        return index;
      }
    }
  }
  return -1;
}

function rustBraceDepthBefore(sourceCode, end) {
  let depth = 0;
  for (let index = 0; index < end; index += 1) {
    if (sourceCode[index] === "{") {
      depth += 1;
    } else if (sourceCode[index] === "}") {
      depth -= 1;
    }
  }
  return depth;
}

function rustCfgMetaCallArgumentsFromLexicalCode(code, name) {
  const prefix = new RegExp(`^${name}\\s*\\(`, "u").exec(code);
  if (prefix === null) {
    return null;
  }
  const opening = code.indexOf("(", prefix.index);
  const closing = matchingRustDelimiter(code, opening, "(", ")");
  if (closing === -1 || code.slice(closing + 1).trim() !== "") {
    return null;
  }
  const argumentsSource = code.slice(opening + 1, closing);
  const argumentsList = [];
  let depth = 0;
  let start = 0;
  for (let index = 0; index <= argumentsSource.length; index += 1) {
    const character = argumentsSource[index];
    if (character === "(") {
      depth += 1;
    } else if (character === ")") {
      depth -= 1;
      if (depth < 0) {
        return null;
      }
    } else if (
      (character === "," || index === argumentsSource.length) &&
      depth === 0
    ) {
      const argument = argumentsSource.slice(start, index).trim();
      if (argument !== "") {
        argumentsList.push(argument);
      }
      start = index + 1;
    }
  }
  return depth === 0 ? argumentsList : null;
}

function rustCfgMetaCallArguments(expression, name) {
  return rustCfgMetaCallArgumentsFromLexicalCode(
    rustLexicalCode(expression).trim(),
    name,
  );
}

function rustCfgExpressionRequiresTest(expression) {
  const code = rustLexicalCode(expression).trim();
  if (code === "test") {
    return true;
  }
  const allArguments = rustCfgMetaCallArguments(code, "all");
  if (allArguments !== null) {
    return allArguments.some((argument) =>
      rustCfgExpressionRequiresTest(argument),
    );
  }
  const anyArguments = rustCfgMetaCallArguments(code, "any");
  if (anyArguments !== null) {
    return (
      anyArguments.length > 0 &&
      anyArguments.every((argument) => rustCfgExpressionRequiresTest(argument))
    );
  }
  return false;
}

function rustCfgExpressionRequiresTestUncached(expression) {
  const code = rustLexicalCodeUncached(expression).trim();
  if (code === "test") {
    return true;
  }
  const allArguments = rustCfgMetaCallArgumentsFromLexicalCode(code, "all");
  if (allArguments !== null) {
    return allArguments.some((argument) =>
      rustCfgExpressionRequiresTestUncached(argument),
    );
  }
  const anyArguments = rustCfgMetaCallArgumentsFromLexicalCode(code, "any");
  if (anyArguments !== null) {
    return (
      anyArguments.length > 0 &&
      anyArguments.every((argument) =>
        rustCfgExpressionRequiresTestUncached(argument),
      )
    );
  }
  return false;
}

const withoutBottomTestModuleCache = new Map();
function withoutBottomTestModuleUncached(source) {
  const sourceCode = rustLexicalCodeUncached(source);
  const candidates = [
    ...sourceCode.matchAll(
      /(?:^|\n)[\t ]*#\s*\[\s*cfg\s*\((?<expression>[^\]\r\n]*)\)\s*\][\t ]*(?:\r?\n[\t ]*)?mod\s+tests\s*\{/gu,
    ),
  ].filter(
    (match) =>
      rustBraceDepthBefore(sourceCode, match.index) === 0 &&
      rustCfgExpressionRequiresTestUncached(match.groups.expression),
  );
  if (candidates.length === 0) {
    return source;
  }
  if (candidates.length !== 1) {
    throw new Error(
      "architecture scan requires exactly one bottom Rust test module",
    );
  }
  const marker = candidates[0];
  const openingBrace = sourceCode.indexOf("{", marker.index);
  const closingBrace = matchingRustDelimiter(
    sourceCode,
    openingBrace,
    "{",
    "}",
  );
  if (closingBrace === -1) {
    throw new Error(
      "architecture scan found an unterminated bottom Rust test module",
    );
  }
  let suffixCursor = closingBrace + 1;
  while (sourceCode.slice(suffixCursor).trim() !== "") {
    const suffix = sourceCode.slice(suffixCursor);
    const continuation =
      /^\s*#\s*\[\s*cfg\s*\((?<expression>[^\]]*)\)\s*\]\s*mod\s+(?<name>[A-Za-z_][A-Za-z0-9_]*_tests)\s*\{/u.exec(
        suffix,
      );
    if (
      continuation === null ||
      !rustCfgExpressionRequiresTestUncached(
        continuation.groups.expression,
      )
    ) {
      throw new Error(
        "architecture scan requires bottom Rust test modules to form the final lexical suffix",
      );
    }
    const continuationStart = suffixCursor + continuation.index;
    const continuationOpening = sourceCode.indexOf("{", continuationStart);
    const continuationClosing = matchingRustDelimiter(
      sourceCode,
      continuationOpening,
      "{",
      "}",
    );
    if (continuationClosing === -1) {
      throw new Error(
        "architecture scan found an unterminated bottom Rust test continuation module",
      );
    }
    suffixCursor = continuationClosing + 1;
  }
  return source.slice(0, marker.index);
}

function withoutBottomTestModule(source) {
  const cached = withoutBottomTestModuleCache.get(source);
  if (cached !== undefined) return cached;
  const production = withoutBottomTestModuleUncached(source);
  withoutBottomTestModuleCache.set(source, production);
  return production;
}

function rustBottomTestModule(source) {
  const production = withoutBottomTestModule(source);
  if (production === source) {
    throw new Error("architecture scan requires a bottom Rust test module");
  }
  return source.slice(production.length);
}

function insertBeforeBottomTestModule(source, insertion) {
  const production = withoutBottomTestModule(source);
  if (production === source) {
    throw new Error("architecture scan requires a bottom Rust test module");
  }
  return `${production}${insertion}${source.slice(production.length)}`;
}

function endOfRustItemAfterAttribute(sourceCode, attributeEnd) {
  let cursor = attributeEnd;
  while (/\s/u.test(sourceCode[cursor] ?? "")) {
    cursor += 1;
  }
  for (;;) {
    const attachedAttribute = /^#\s*\[/u.exec(sourceCode.slice(cursor));
    if (attachedAttribute === null) {
      break;
    }
    const openingBracket = cursor + attachedAttribute[0].lastIndexOf("[");
    const closingBracket = matchingRustDelimiter(
      sourceCode,
      openingBracket,
      "[",
      "]",
    );
    if (closingBracket === -1) {
      return -1;
    }
    cursor = closingBracket + 1;
    while (/\s/u.test(sourceCode[cursor] ?? "")) {
      cursor += 1;
    }
  }

  const itemSource = sourceCode.slice(cursor);
  const visibility = String.raw`(?:pub(?:\s*\([^)]*\))?\s+)?`;
  const bracedOrSemicolonItem = new RegExp(
    `^${visibility}(?:(?:(?:const|async|unsafe)\\s+)*(?:extern(?:\\s+"[^"\\r\\n]*")?\\s+)?fn\\b|(?:unsafe\\s+)?(?:impl|trait)\\b|(?:struct|enum|union|mod)\\b|(?:unsafe\\s+)?extern(?:\\s+"[^"\\r\\n]*")?\\s*\\{)`,
    "u",
  ).test(itemSource);
  const semicolonItem = new RegExp(
    `^${visibility}(?:use\\b|type\\s+(?:r#)?[\\p{XID_Start}_][\\p{XID_Continue}_]*\\b|const\\s+(?:(?:r#)?[\\p{XID_Start}_][\\p{XID_Continue}_]*|_)\\s*:|static\\s+(?:mut\\s+)?(?:r#)?[\\p{XID_Start}_][\\p{XID_Continue}_]*\\s*:|extern\\s+crate\\b)`,
    "u",
  ).test(itemSource);
  if (!bracedOrSemicolonItem && !semicolonItem) {
    return null;
  }

  let parentheses = 0;
  let brackets = 0;
  let braces = 0;
  for (let index = cursor; index < sourceCode.length; index += 1) {
    switch (sourceCode[index]) {
      case "(":
        parentheses += 1;
        break;
      case ")":
        parentheses -= 1;
        break;
      case "[":
        brackets += 1;
        break;
      case "]":
        brackets -= 1;
        break;
      case "{":
        if (
          bracedOrSemicolonItem &&
          parentheses === 0 &&
          brackets === 0 &&
          braces === 0
        ) {
          const closingBrace = matchingRustDelimiter(
            sourceCode,
            index,
            "{",
            "}",
          );
          return closingBrace === -1 ? -1 : closingBrace + 1;
        }
        braces += 1;
        break;
      case "}":
        braces -= 1;
        if (braces < 0) {
          return -1;
        }
        break;
      case ";":
        if (parentheses === 0 && brackets === 0 && braces === 0) {
          return index + 1;
        }
        break;
      default:
        break;
    }
  }
  return -1;
}

const withoutCfgTestItemsCache = new Map();
function withoutCfgTestItemsUncached(source) {
  const sourceCode = rustLexicalCodeUncached(source);
  const characters = source.split("");
  for (const attribute of sourceCode.matchAll(
    /#\s*\[\s*cfg\s*\(\s*test\s*\)\s*\]/gu,
  )) {
    const end = endOfRustItemAfterAttribute(
      sourceCode,
      attribute.index + attribute[0].length,
    );
    if (end === null) {
      continue;
    }
    if (end === -1) {
      throw new Error(
        "architecture scan could not bound a cfg(test) Rust item",
      );
    }
    maskRustRange(characters, source, attribute.index, end);
  }
  return characters.join("");
}

function withoutCfgTestItems(source) {
  const cached = withoutCfgTestItemsCache.get(source);
  if (cached !== undefined) return cached;
  const production = withoutCfgTestItemsUncached(source);
  withoutCfgTestItemsCache.set(source, production);
  return production;
}

