const mutateKeyAgentServiceWireSource = (suffix) =>
  keyAgentServiceWireRustFiles.map((file) =>
    file.path === "crates/key-agent-service-wire/src/lib.rs"
      ? { ...file, source: `${file.source}\n${suffix}\n` }
      : file,
  );
