function hasOrderedCompactMarkers(source, markers) {
  const compact = compactRust(source);
  let cursor = 0;
  return markers.every((marker) => {
    const index = compact.indexOf(marker, cursor);
    if (index === -1) return false;
    cursor = index + marker.length;
    return true;
  });
}

